t2-count-vowels.code:
class Solution {
    static int countVowels(String s) {
      int count = 0;
      for (char c : s.toLowerCase()) {
        if ("aeiouy".contains(c)) {
          ++count;
        }
      }
      return count;
    }
}

t2-normalize-space.code:
class Solution {
    static String normalize(String s) {
        return s.strip().replaceAll('\s', ' ');
    }
}

t2-reverse-words.code:
class Solution {
    static String reverseWords(String s) {
        String[] arr = s.split(" ").reverse();
        return arr.join(" ");
    }
}
